 */
function escapeMarkdownV2(text) {
    // Порядок важен! Сначала экранируем обратный слэш
    let escaped = text.replace(/\\/g, '\\\\');

    // Затем экранируем остальные специальные символы
    escaped = escaped.replace(/_/g, '\\_');     // Подчеркивание
