    escaped = escaped.replace(/~/g, '\\~');     // Тильда
    escaped = escaped.replace(/`/g, '\\`');     // Обратная кавычка
    escaped = escaped.replace(/>/g, '\\>');     // Больше
    escaped = escaped.replace(/#/g, '\\#');     // Решетка
    escaped = escaped.replace(/\+/g, '\\+');    // Плюс
    escaped = escaped.replace(/-/g, '\\-');     // Минус
    escaped = escaped.replace(/=/g, '\\=');     // Равно
    escaped = escaped.replace(/\|/g, '\\|');    // Вертикальная черта
    escaped = escaped.replace(/\{/g, '\\{');    // Открывающая фигурная скобка
    escaped = escaped.replace(/\}/g, '\\}');    // Закрывающая фигурная скобка
    escaped = escaped.replace(/\./g, '\\.');    // Точка
    escaped = escaped.replace(/!/g, '\\!');     // Восклицательный знак

    return escaped;
}

/**
 * Функция для применения форматирования MarkdownV2
 */
function applyMarkdownV2Formatting(text) {
    let processedText = text;

    // Заменяем заголовки на жирный текст (от более длинных к коротким)
    // ### заголовок -> *заголовок*
    processedText = processedText.replace(/^###\s+(.+)$/gm, '*$1*');

    // ## заголовок -> *заголовок*  
    processedText = processedText.replace(/^##\s+(.+)$/gm, '*$1*');

    // # заголовок -> *заголовок*
    processedText = processedText.replace(/^#\s+(.+)$/gm, '*$1*');

    // Заменяем жирный текст: **текст** -> *текст*
    processedText = processedText.replace(/\*\*(.+?)\*\*/g, '*$1*');

    // Заменяем курсив: *текст* -> _текст_ (только одиночные звездочки, не входящие в пары)
    // Используем отрицательные lookbehind и lookahead для избежания конфликтов
    processedText = processedText.replace(/(?<!\*)\*([^*\n]+?)\*(?!\*)/g, '_$1_');

    return processedText;
}

