function processTextForTelegramMarkdownV2(inputText) {
    // 1. Сначала применяем форматирование
    let processedText = applyMarkdownV2Formatting(inputText);

    // 2. Теперь разбиваем текст на форматированные и обычные части
    const parts = [];
    let currentIndex = 0;

    // Регекс для поиска всех форматированных областей
    const formattedRegex = /(\*[^*\n]+?\*|_[^_\n]+?_|`[^`\n]*?`|```[\s\S]*?```)/g;
    let match;

    while ((match = formattedRegex.exec(processedText)) !== null) {
        // Добавляем обычный текст до форматированной области
        if (match.index > currentIndex) {
            const plainText = processedText.substring(currentIndex, match.index);
            parts.push({ type: 'plain', text: plainText });
        }

        // Добавляем форматированную область
        parts.push({ type: 'formatted', text: match[0] });
        currentIndex = match.index + match[0].length;
    }

    // Добавляем оставшийся текст
    if (currentIndex < processedText.length) {
        const plainText = processedText.substring(currentIndex);
        parts.push({ type: 'plain', text: plainText });
    }

    // 3. Экранируем символы
    const finalText = parts.map(part => {
        if (part.type === 'plain') {
            // Обычный текст - экранируем все специальные символы
            return escapeMarkdownV2(part.text);
        } else {
            // Форматированный текст - экранируем только содержимое
            if (part.text.startsWith('*') && part.text.endsWith('*') && part.text.length > 2) {
                // Жирный текст: *содержимое*
                const content = part.text.slice(1, -1);
                return '*' + escapeMarkdownV2(content) + '*';
            } else if (part.text.startsWith('_') && part.text.endsWith('_') && part.text.length > 2) {
                // Курсив: _содержимое_
                const content = part.text.slice(1, -1);
                return '_' + escapeMarkdownV2(content) + '_';
            } else if (part.text.startsWith('`') && part.text.endsWith('`') && !part.text.startsWith('```')) {
                // Инлайн код: `содержимое`
                const content = part.text.slice(1, -1);
                // В коде экранируем только \ и `
                const escapedContent = content.replace(/\\/g, '\\\\').replace(/`/g, '\\`');
                return '`' + escapedContent + '`';
            } else if (part.text.startsWith('```') && part.text.endsWith('```')) {
                // Блок кода: ```содержимое```
                const content = part.text.slice(3, -3);
                // В блоке кода экранируем только \ и `
                const escapedContent = content.replace(/\\/g, '\\\\').replace(/`/g, '\\`');
                return '```' + escapedContent + '```';
            }
            // Если не распознали тип, возвращаем как есть (не должно происходить)
            return part.text;
        }
    }).join('');

    return finalText;
}

