const text = $('Markdown V2 formatting').first().json.output || '';
const maxLength = 4070;

// Функция для разделения текста на части
function splitText(inputText, partNumber = 1) {
  const parts = [];
  let remainingText = inputText;
  let currentPartNumber = partNumber;

  while (remainingText.length > maxLength) {
    // Ищем место для разделения (последний пробел до позиции maxLength)
    let splitPosition = maxLength;

    // Ищем последний пробел, новую строку или другой разделитель перед позицией maxLength
    while (splitPosition > 0) {
      const char = remainingText[splitPosition];
      if (char === ' ' || char === '\n' || char === '\t' || char === '\r') {
        break;
      }
      splitPosition--;
    }

    // Если не нашли подходящее место для разделения, используем maxLength
    if (splitPosition === 0) {
      splitPosition = maxLength;
    }

    // Создаем текущую часть
    const currentPart = remainingText.substring(0, splitPosition).trim();
    parts.push({
      [`part${currentPartNumber}`]: currentPart,
      [`part${currentPartNumber}_length`]: currentPart.length
    });

    // Обновляем оставшийся текст
    remainingText = remainingText.substring(splitPosition).trim();
    currentPartNumber++;
  }

  // Добавляем последнюю часть, если она есть
  if (remainingText.length > 0) {
    parts.push({
      [`part${currentPartNumber}`]: remainingText,
      [`part${currentPartNumber}_length`]: remainingText.length
    });
  }

  return parts;
}

